#include <Nodrix.h>
#include <DHT.h>

DHT dht(4, DHT11);
const int FAN_PIN = 5;
unsigned long lastSend = 0;

NODRIX_WRITE("fan") {
  digitalWrite(FAN_PIN, value.asBool());
}

void setup() {
  pinMode(FAN_PIN, OUTPUT);
  dht.begin();
  Nodrix.begin(WIFI_SSID, WIFI_PASS, HOST, TOKEN);
}

void loop() {
  Nodrix.run();

  if (millis() - lastSend > 5000) {
    lastSend = millis();
    float t = dht.readTemperature();
    if (!isnan(t)) Nodrix.send("temperature", t);
  }
